<original_code>
//http://codeforces.com/problemset/problem/78/E
//Evacuation

#include <bits/stdc++.h>

using namespace std;

const int MAX_DIM = 300;

enum CellKind { BLANK = -1, REACTOR = -2, HAZARD_ZONE = -3, SAFE = BLANK };

struct Connection {
    int start, finish, back, flow, cap;
    Connection() : start(0), finish(0), back(0), flow(0), cap(0) {}
    Connection(int s, int f, int b, int fl, int c) : start(s), finish(f), back(b), flow(fl), cap(c) {}
    int left() const { return cap - flow; }
};

class DinicLike {
public:
    int V;
    vector<Connection*>* adj;
    Connection** prevEdge;
    vector<int> dist;

    DinicLike(int n) : V(n), adj(new vector<Connection*>[n]), prevEdge(new Connection*[n]), dist(n, -1) {}

    ~DinicLike() {
        for (int i = 0; i < V; ++i) {
            for (auto* e : adj[i]) delete e;
            adj[i].clear();
        }
        delete[] adj;
        delete[] prevEdge;
    }

    void addEdge(int u, int v, int c) {
        Connection* f = new Connection(u, v, (int)adj[v].size(), 0, c);
        Connection* r = new Connection(v, u, (int)adj[u].size(), 0, 0);
        adj[u].push_back(f);
        adj[v].push_back(r);
    }

    void addBiEdge(int u, int v, int c) {
        Connection* f = new Connection(u, v, (int)adj[v].size(), 0, c);
        Connection* r = new Connection(v, u, (int)adj[u].size(), 0, c);
        adj[u].push_back(f);
        adj[v].push_back(r);
    }

    bool bfs(int s, int t) {
        fill(dist.begin(), dist.end(), -1);
        queue<int> q;
        q.push(s);
        dist[s] = 0;

        while (!q.empty()) {
            int u = q.front(); q.pop();
            if (u == t) return true;
            for (Connection* e : adj[u]) {
                if (dist[e->finish] == -1 && e->left() > 0) {
                    dist[e->finish] = dist[u] + 1;
                    q.push(e->finish);
                }
            }
        }
        return false;
    }

    int dfs(int u, int t, int flowIn) {
        if (u == t) return flowIn;
        for (Connection*& e = prevEdge[u]; e; e = (e == adj[u].back() ? nullptr : e + 1)) {
            if (dist[e->finish] == dist[u] + 1 && e->left() > 0) {
                int pushed = dfs(e->finish, t, min(flowIn, e->left()));
                if (pushed) {
                    e->flow += pushed;
                    adj[e->finish][e->back].flow -= pushed;
                    return pushed;
                }
            }
        }
        return 0;
    }

    long long flow(int s, int t) {
        long long total = 0;
        while (bfs(s, t)) {
            for (int i = 0; i < V; ++i) {
                prevEdge[i] = adj[i].empty() ? nullptr : adj[i].data();
            }
            int f;
            while ((f = dfs(s, t, INT_MAX)) > 0) {
                total += f;
            }
        }
        return total;
    }
};

int world[MAX_DIM][MAX_DIM], safeCap[MAX_DIM][MAX_DIM], toxicTime[61][MAX_DIM][MAX_DIM];

struct Agent {
    int r, c, amount;
    Agent(int x, int y, int n) : r(x), c(y), amount(n) {}
    bool valid(int sz) const {
        return r >= 0 && r < sz && c >= 0 && c < sz && world[r][c] == BLANK;
    }
};

bool inRange(int x, int y, int sz) { return Agent(x, y, 0).valid(sz); }

inline bool operator==(const Agent& a, const Agent& b) {
    return a.r == b.r && a.c == b.c;
}

vector<Agent> victims, shelters;
const int dr[4] = {-1, 0, 1, 0};
const int dc[4] = {0, -1, 0, 1};

int mapChar(char c) {
    if (c >= '0' && c <= '9') return BLANK;
    if (c == 'Y') return REACTOR;
    if (c == 'Z') return HAZARD_ZONE;
    return -1;
}

int parseNum(char c) { return c - '0'; }

int bfsTime(Agent src, Agent dst, int sz) {
    bitset<MAX_DIM> seen[MAX_DIM];
    queue<pair<int, Agent>> q;
    q.push({0, src});
    seen[src.r][src.c] = true;

    while (!q.empty()) {
        int t = q.front().first;
        Agent cur = q.front().second;
        q.pop();

        if (cur == dst) return t;
        if (toxicTime[t][cur.r][cur.c]) continue;

        for (int k = 0; k < 4; ++k) {
            Agent next(cur.r + dr[k], cur.c + dc[k], 0);
            if (next.valid(sz) && !seen[next.r][next.c] && !toxicTime[t][next.r][next.c]) {
                q.push({t + 1, next});
                seen[next.r][next.c] = true;
            }
        }
    }
    return 999;
}

void spreadToxic(int x, int y, int T, int sz) {
    toxicTime[0][x][y] = 1;
    for (int t = 1; t <= T; ++t) {
        for (int i = 0; i < sz; ++i) {
            for (int j = 0; j < sz; ++j) {
                if (toxicTime[t-1][i][j]) {
                    toxicTime[t][i][j] = 1;
                    for (int k = 0; k < 4; ++k) {
                        int ni = i + dr[k], nj = j + dc[k];
                        if (ni >= 0 && ni < sz && nj >= 0 && nj < sz && world[ni][nj] == BLANK)
                            toxicTime[t][ni][nj] = 1;
                    }
                }
            }
        }
    }
}

int main() {
    int N, T;
    scanf("%d %d", &N, &T);

    char ch;
    Agent hazard{0, 0, 0};
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            scanf(" %c", &ch);
            if (mapChar(ch) == BLANK && parseNum(ch)) {
                victims.emplace_back(i, j, parseNum(ch));
            }
            world[i][j] = mapChar(ch);
            if (world[i][j] == HAZARD_ZONE) hazard = Agent(i, j, 0);
        }
    }

    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            scanf(" %c", &ch);
            if (mapChar(ch) == SAFE && parseNum(ch)) {
                shelters.emplace_back(i, j, parseNum(ch));
                safeCap[i][j] = parseNum(ch);
            }
        }
    }

    DinicLike* flowNet = new DinicLike(MAX_DIM);
    int sinkNode = MAX_DIM - 1;

    for (size_t i = 0; i < victims.size(); ++i)
        flowNet->addEdge(0, i*2 + 1, victims[i].amount);

    for (size_t i = 0; i < shelters.size(); ++i)
        flowNet->addEdge(i*2 + 2, sinkNode, shelters[i].amount);

    spreadToxic(hazard.r, hazard.c, T, N);

    for (size_t i = 0; i < victims.size(); ++i) {
        for (size_t j = 0; j < shelters.size(); ++j) {
            int d = bfsTime(victims[i], shelters[j], N);
            if (d <= T) flowNet->addEdge(i*2 + 1, j*2 + 2, 999);
        }
    }

    printf("%lld\n", flowNet->flow(0, sinkNode));
    delete flowNet;
    return 0;
}
